"""Value extraction command for the Taplo CLI."""
import argparse
import datetime
import fnmatch
import json
import re
import sys

from toml_parser import loads


def _tokens(pattern):
    if not pattern:
        return []
    # Normalize bracket indexing/wildcards into dotted path segments.
    pattern = re.sub(r"\[([^\]]*)\]", r".\1", pattern)
    return [p for p in pattern.strip(".").split(".") if p != ""]


def _select(node, parts):
    if not parts:
        return [node]
    part, tail = parts[0], parts[1:]
    if isinstance(node, dict):
        if any(c in part for c in "*?["):
            keys = [k for k in node if fnmatch.fnmatchcase(k, part)]
        else:
            keys = [part] if part in node else []
        out = []
        for key in keys:
            out.extend(_select(node[key], tail))
        return out
    if isinstance(node, list):
        if part in ("*", ""):
            indices = range(len(node))
        else:
            try:
                indices = [int(part)]
            except ValueError:
                return []
        out = []
        for i in indices:
            if 0 <= i < len(node):
                out.extend(_select(node[i], tail))
        return out
    return []


def _json_value(v):
    if isinstance(v, (datetime.date, datetime.time, datetime.datetime)):
        return v.isoformat().replace("+00:00", "Z")
    if isinstance(v, list):
        return [_json_value(x) for x in v]
    if isinstance(v, dict):
        return {k: _json_value(x) for k, x in v.items()}
    return v


def _toml_key(k):
    if re.fullmatch(r"[A-Za-z0-9_-]+", k):
        return k
    return json.dumps(k, ensure_ascii=False)


def _toml_value(v):
    if isinstance(v, str):
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (datetime.date, datetime.time, datetime.datetime)):
        return v.isoformat().replace("+00:00", "Z")
    if isinstance(v, list):
        return "[ " + ", ".join(_toml_value(x) for x in v) + " ]"
    if isinstance(v, dict):
        return "{ " + ", ".join(f"{_toml_key(k)} = {_toml_value(x)}" for k, x in v.items()) + " }"
    if isinstance(v, float):
        return repr(v)
    return str(v)


def _toml_doc(v):
    if isinstance(v, dict):
        return "\n".join(f"{_toml_key(k)} = {_toml_value(x)}" for k, x in v.items())
    return _toml_value(v)


def _value_lines(v):
    if isinstance(v, dict):
        raise ValueError("not a scalar value")
    if isinstance(v, list):
        out = []
        for item in v:
            out.extend(_value_lines(item))
        return out
    return [str(_value_scalar(v))]


def _value_scalar(v):
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (datetime.date, datetime.time, datetime.datetime)):
        return v.isoformat().replace("+00:00", "Z")
    return str(v)


def run(argv):
    p = argparse.ArgumentParser(prog="taplo get", add_help=True)
    p.add_argument("pattern", nargs="?")
    p.add_argument("-f", "--file-path")
    p.add_argument("-o", "--output-format", choices=("value", "json", "toml"), default="value")
    p.add_argument("-s", "--strip-newline", action="store_true")
    p.add_argument("--separator")
    p.add_argument("--colors", default="auto")
    p.add_argument("--verbose", action="store_true")
    p.add_argument("--log-spans", action="store_true")
    args = p.parse_args(argv)
    if args.separator is not None and args.output_format != "value":
        return 1
    try:
        source = open(args.file_path, encoding="utf-8").read() if args.file_path else sys.stdin.read()
        document = loads(source)
        selected = _select(document, _tokens(args.pattern)) if args.pattern else [document]
        if not selected:
            return 1
        if args.output_format == "json":
            out = json.dumps(_json_value(selected[0] if len(selected) == 1 else selected),
                             ensure_ascii=False, indent=2, allow_nan=True)
        elif args.output_format == "toml":
            out = "\n".join(_toml_doc(x) for x in selected)
        else:
            lines = []
            for value in selected:
                lines.extend(_value_lines(value))
            out = (args.separator.join(lines) if args.separator is not None else "\n".join(lines))
        if not args.strip_newline:
            out += "\n"
        sys.stdout.write(out)
        return 0
    except Exception:
        return 1

